//! TK-155/156: partial fills are generated by the real matcher, with bounded windows.
use hft_event::{Bbo, EventKind, GwCmd, GwOp, OrderEvent, OrderEventKind};
use hft_testkit::dst::faults::Fault;
use hft_testkit::dst::seq::matcher::SimMatcher;
use hft_testkit::dst::sut::InputRec;
use hft_testkit::dst::venue_behavior::{Matcher, MockVenue, MockVenueCfg, ToyMatcher};
use hft_testkit::dst::world::{ACCT_A, BTC, P1, S1, USDT, VP, VS, WorldSpec};
use hft_testkit::dst::{DstConfig, InvariantSet, SeqSut, run_record};
use hft_types::{InstId, Px, Qty, Side, SlotId, Tif, Tsc, VenueId};
use zerocopy::TryFromBytes;

/// Keep the same event plan, ordering and random draws, but reproduce the former no-op.
/// Historical actor migration tests also use this to isolate their own change.
pub(super) fn without_partial(cfg: &DstConfig) -> DstConfig {
    let mut cfg = cfg.clone();
    let mut plan = cfg.fault_plan();
    for (_, fault) in &mut plan.items {
        if let Fault::PartialFills { dur_ms, .. } = fault {
            *dur_ms = 0;
        }
    }
    cfg.plan = Some(plan);
    cfg
}

fn venue<M: Matcher>(world: &WorldSpec, venue: VenueId) -> MockVenue<M> {
    let mut cfg = MockVenueCfg::w1(venue);
    cfg.rate_per_s = 0;
    cfg.bbo_ping_ms = 0;
    cfg.latency_ns = (0, 0);
    cfg.md_latency_ns = (0, 0);
    MockVenue::new(cfg, world, 1)
}

fn place(inst: InstId, side: Side, tif: Tif, qty: i64, px: i64, slot: u32) -> GwCmd {
    GwCmd {
        decision_seq: u64::from(slot),
        decided_tsc: Tsc(0),
        px: Px(px),
        qty: Qty(qty),
        inst,
        slot: SlotId(slot),
        r#gen: 3,
        target_slot: SlotId(0),
        op: GwOp::Place,
        account: ACCT_A,
        side,
        tif,
        oflags: 0,
        _pad: [0; 2],
        arg: 7,
        arg2: 0,
    }
}

fn events(rows: &[(u64, InputRec)]) -> Vec<OrderEvent> {
    rows.iter()
        .filter(|(_, r)| r.kind == EventKind::ORDER_EVENT)
        .map(|(_, r)| OrderEvent::try_read_from_bytes(&r.body).unwrap())
        .collect()
}

fn total<K: Copy + PartialEq>(rows: &[(K, i128)], key: K) -> i128 {
    rows.iter().find(|(k, _)| *k == key).map_or(0, |(_, v)| *v)
}

#[test]
fn tk_155_partial_fills_use_matcher_fees_cash_and_ioc_fok_rules() {
    for (venue_id, inst, base_fee) in [(VS, S1, false), (VS, S1, true), (VP, P1, false)] {
        for side in [Side::Buy, Side::Sell] {
            for tif in [Tif::Ioc, Tif::Fok] {
                let mut world = WorldSpec::w1();
                world
                    .venues
                    .iter_mut()
                    .find(|v| v.id == venue_id)
                    .unwrap()
                    .fee_in_base = base_fee;
                world.accounts[0].balances.push((VS, BTC, 100_000_000));
                let instrument = world.insts.iter().find(|i| i.id == inst).unwrap();
                let lot = instrument.lot;
                let mut v = venue::<SimMatcher>(&world, venue_id);
                assert!(v.m.is_ready());
                v.on_market(inst, (599_000_000, 100 * lot), (600_000_000, 100 * lot), 0);
                let before = v.m.truth(ACCT_A);
                v.apply_fault(
                    &Fault::PartialFills {
                        venue: venue_id,
                        dur_ms: 100,
                    },
                    0,
                );
                let px = if side == Side::Buy {
                    600_000_000
                } else {
                    599_000_000
                };
                let cmd = place(inst, side, tif, 10 * lot, px, 1);
                let reports = events(&v.on_frame(&cmd, 20_000_000));
                assert!(v.fault_error().is_none());
                let fills: Vec<_> = reports
                    .iter()
                    .filter(|r| {
                        r.qty.0 > 0 && matches!(r.what, OrderEventKind::PartialFill | OrderEventKind::Fill)
                    })
                    .collect();
                let after = v.m.truth(ACCT_A);
                if tif == Tif::Fok {
                    assert!(fills.is_empty(), "FOK must not become a partial execution");
                    assert!(reports.iter().any(|e| e.what == OrderEventKind::Expired));
                    assert_eq!(before.positions, after.positions);
                    assert_eq!(before.inventory, after.inventory);
                    assert_eq!(before.balances, after.balances);
                    continue;
                }
                assert_eq!(fills.len(), 1, "{venue_id:?}/{side:?}: {reports:?}");
                let e = fills[0];
                assert_eq!(
                    (e.what, e.qty.0, e.cum_filled.0),
                    (OrderEventKind::PartialFill, lot, lot)
                );
                assert_eq!((e.epoch, e.slot, e.r#gen), (7, cmd.slot, 3));
                assert!(
                    reports
                        .iter()
                        .any(|r| r.what == OrderEventKind::Expired && r.cum_filled.0 == lot)
                );
                // W1 exponents: px=-4, qty=-8, USDT=-6. Compute from the command and
                // the independent one-lot liquidity contract, never from a wallet delta.
                let sign = if side == Side::Buy { 1_i128 } else { -1_i128 };
                let notional = i128::from(px) * i128::from(lot) / 1_000_000;
                let ppm = if venue_id == VS { 1_000 } else { 500 };
                let (fee_n, fee_d) = if base_fee {
                    // Configured(BTC) converts gross notional at the input BBO mid.
                    // Preserve the half tick and round only once, at the final asset unit.
                    (
                        2 * i128::from(px) * i128::from(lot) * ppm,
                        1_199_000_000 * 1_000_000,
                    )
                } else {
                    (i128::from(px) * i128::from(lot) * ppm, 1_000_000 * 1_000_000)
                };
                let fee = (fee_n + fee_d - 1) / fee_d;
                assert_eq!(
                    (e.fee_asset, i128::from(e.fee.0)),
                    (if base_fee { BTC } else { USDT }, fee)
                );
                let cash = if venue_id == VS { -sign * notional } else { 0 };
                let quote_fee = if base_fee { 0 } else { fee };
                assert_eq!(
                    total(&after.balances, USDT),
                    total(&before.balances, USDT) + cash - quote_fee
                );
                if venue_id == VS {
                    assert_eq!(
                        total(&after.inventory, BTC),
                        total(&before.inventory, BTC) + sign * i128::from(lot)
                            - if base_fee { fee } else { 0 }
                    );
                } else {
                    assert_eq!(
                        total(&after.positions, inst),
                        total(&before.positions, inst) + sign * i128::from(lot)
                    );
                    assert_eq!((e.cash_qty.0, e.cash_sum.0), (lot, 0));
                }
            }
        }
    }
}

#[test]
fn tk_155_partial_window_restores_latest_book_and_respects_arrival_boundary() {
    let world = WorldSpec::w1();
    let lot = world.insts.iter().find(|i| i.id == S1).unwrap().lot;
    let mut v = venue::<SimMatcher>(&world, VS);
    v.apply_fault(
        &Fault::PartialFills {
            venue: VS,
            dur_ms: 100,
        },
        0,
    );
    let first = place(S1, Side::Buy, Tif::Ioc, 10 * lot, 600_000_000, 1);
    assert!(
        events(&v.on_frame(&first, 20_000_000))
            .iter()
            .any(|r| r.what == OrderEventKind::PartialFill)
    );
    // The union of overlapping windows ends at 200 ms, not the first window's 100 ms.
    v.apply_fault(
        &Fault::PartialFills {
            venue: VS,
            dur_ms: 150,
        },
        50_000_000,
    );
    let (_, advertised) = v
        .on_market(S1, (600_999_900, 40 * lot), (601_000_000, 40 * lot), 50_000_000)
        .unwrap();
    assert_eq!(advertised.read::<Bbo>().unwrap().ask_qty.0, 40 * lot);
    v.tick(100_000_000);
    let second = place(S1, Side::Buy, Tif::Ioc, 10 * lot, 601_000_000, 2);
    assert!(
        events(&v.on_frame(&second, 120_000_000))
            .iter()
            .any(|r| r.what == OrderEventKind::PartialFill && r.qty.0 == lot)
    );
    v.on_market(S1, (601_999_900, 30 * lot), (602_000_000, 30 * lot), 150_000_000);
    v.tick(150_000_000);
    assert_eq!(v.next_wake(150_000_000), 200_000_000);
    // Entry delay is 1 ms: collection at 199.5 ms must not match this order early
    // against thin liquidity. No market update is provided at/after expiry.
    let last = place(S1, Side::Buy, Tif::Ioc, 10 * lot, 602_000_000, 3);
    let early = events(&v.on_frame(&last, 199_500_000));
    assert!(
        !early
            .iter()
            .any(|r| matches!(r.what, OrderEventKind::Fill | OrderEventKind::PartialFill))
    );
    let restored = events(&v.tick(200_000_000));
    assert!(
        restored
            .iter()
            .any(|r| r.what == OrderEventKind::Fill && r.qty.0 == 10 * lot && r.px.0 == 602_000_000)
    );
    assert!(!restored.iter().any(|r| r.what == OrderEventKind::PartialFill));
}

#[test]
fn tk_155_partial_clean_zero_and_invalid_windows_are_explicit() {
    let world = WorldSpec::w1();
    let cmd = place(S1, Side::Buy, Tif::Ioc, 10_000, 600_000_000, 1);
    for (clean, duration) in [(true, 100), (false, 0)] {
        let mut v = venue::<SimMatcher>(&world, VS);
        v.clean = clean;
        v.apply_fault(
            &Fault::PartialFills {
                venue: VS,
                dur_ms: duration,
            },
            0,
        );
        let e = events(&v.on_frame(&cmd, 20_000_000));
        assert!(
            e.iter()
                .any(|r| r.what == OrderEventKind::Fill && r.qty.0 == cmd.qty.0)
        );
        assert!(!e.iter().any(|r| r.what == OrderEventKind::PartialFill));
    }
    let mut v = venue::<ToyMatcher>(&world, VS);
    v.apply_fault(&Fault::PartialFills { venue: VS, dur_ms: 1 }, u64::MAX);
    assert_eq!(v.fault_error(), Some("partial fill window exceeds virtual time"));
    let mut invalid = world.clone();
    invalid.insts.iter_mut().find(|i| i.id == S1).unwrap().lot = 0;
    let mut v = venue::<ToyMatcher>(&invalid, VS);
    v.apply_fault(&Fault::PartialFills { venue: VS, dur_ms: 1 }, 0);
    assert_eq!(
        v.fault_error(),
        Some("partial fills require positive instrument lots")
    );
}

#[test]
fn tk_156_real_partial_fee_windows_keep_wallets_replay_and_checkers_equal() {
    type Engine = SeqSut<crate::fee_cycle::FeeStrategies>;
    for delay_ms in [50, 6_000] {
        let mut cfg = crate::fee_cycle::config(delay_ms);
        cfg.scripted.push((
            0,
            Fault::PartialFills {
                venue: VS,
                dur_ms: 5_000,
            },
        ));
        let on = run_record::<Engine>(&cfg);
        assert!(
            on.outcome.is_pass(),
            "delay={delay_ms}: {:?}",
            on.outcome.failure().map(|f| (&f.invariant, f.message.as_str()))
        );
        assert_eq!(on.steps_run, 10_000);
        let partials: Vec<_> = on
            .journal
            .iter()
            .filter_map(|r| r.try_read::<OrderEvent>())
            .filter(|e| e.what == OrderEventKind::PartialFill && e.venue == VS)
            .collect();
        assert!(!partials.is_empty(), "fault never produced a partial execution");
        assert!(partials.iter().any(|e| e.qty.0 == 1_000));
        let fees: Vec<_> = on
            .journal
            .iter()
            .filter_map(|r| r.try_read::<OrderEvent>())
            .filter(|e| e.what == OrderEventKind::FeeOnly)
            .collect();
        assert_eq!(fees.len(), 1);
        // First buy: ceil(2 * 600000000 * 1000 * 1000 / (1199999900 * 1000000)).
        assert_eq!((fees[0].fee_asset, fees[0].fee.0), (BTC, 2));
        assert!(
            on.journal
                .iter()
                .filter_map(|r| r.try_read::<OrderEvent>())
                .any(|e| e.what == OrderEventKind::Fill && e.venue == VS && e.qty.0 > 1_000),
            "normal matching did not resume after the window"
        );
        assert!(on.journal_verification.is_some());
        assert!(on.snapshot_checks > 0);
        cfg.invariants = InvariantSet::none();
        let off = run_record::<Engine>(&cfg);
        assert!(off.outcome.is_pass());
        assert_eq!(on.journal.len(), off.journal.len());
        for (ix, (a, b)) in on.journal.iter().zip(&off.journal).enumerate() {
            assert!(a == b, "delay={delay_ms}: checker changes record {ix}");
        }
        assert_eq!(on.frames, off.frames);
        assert_eq!(on.deliveries, off.deliveries);
        assert_eq!(on.trail.to_bytes(), off.trail.to_bytes());
        assert_eq!(on.truth, off.truth);
    }
}
